import wixData from "wix-data";
import { ok, badRequest, serverError } from "wix-http-functions";
import { createBooking } from "backend/bookingEngine";
import { INSURANCE_OPTIONS } from "backend/bookingConfig";
import { getPublicPricingCatalog } from "backend/pricingCatalog.jsw";
function respond(body, fn = ok){ return fn({ headers: {"Content-Type":"application/json","Cache-Control":"no-store","Access-Control-Allow-Origin":"*","Access-Control-Allow-Methods":"GET, POST, OPTIONS","Access-Control-Allow-Headers":"Content-Type"}, body }); }
function readOrigin(request){ const origin = String(request?.headers?.origin || '').trim(); if (origin) return origin; const referer = String(request?.headers?.referer || '').trim(); if (!referer) return ''; try { return new URL(referer).origin; } catch (_) { return ''; } }
function parseCsv(value){ return String(value || '').split(',').map((item) => item.trim()).filter(Boolean); }
function normalizeOrigin(origin){ try { return new URL(String(origin || '')).origin; } catch (_) { return ''; } }
function getMutationOriginAllowlist(){ return parseCsv((typeof process !== 'undefined' && process?.env?.BOOKING_MUTATION_ALLOWED_ORIGINS) || '').map((item) => normalizeOrigin(item)).filter(Boolean); }
function isAllowedMutationOrigin(request){ const origin = normalizeOrigin(readOrigin(request)); if (!origin) return false; const allowlist = getMutationOriginAllowlist(); if (allowlist.length) return allowlist.includes(origin); const host = String(request?.headers?.host || '').trim(); if (!host) return false; return origin === normalizeOrigin(`https://${host}`) || origin === normalizeOrigin(`http://${host}`); }
function jsonCorsHeadersForMutation(request){ const origin = normalizeOrigin(readOrigin(request)); const headers = {"Access-Control-Allow-Methods":"POST, OPTIONS","Access-Control-Allow-Headers":"Content-Type","Vary":"Origin"}; if (origin && isAllowedMutationOrigin(request)) headers["Access-Control-Allow-Origin"] = origin; return headers; }
function respondRestricted(request, body, fn = ok){ const origin = normalizeOrigin(readOrigin(request)); const headers = {"Content-Type":"application/json","Cache-Control":"no-store","Access-Control-Allow-Methods":"POST, OPTIONS","Access-Control-Allow-Headers":"Content-Type","Vary":"Origin"}; if (origin && isAllowedMutationOrigin(request)) headers["Access-Control-Allow-Origin"] = origin; return fn({ headers, body }); }
function toImageUrl(value){ const src = value?.src || value; if (!src) return ""; const s = String(src); if (s.startsWith("http://") || s.startsWith("https://")) return s; const m = s.match(/^wix:image:\/\/v1\/([^\/]+)\//); if (m) return `https://static.wixstatic.com/media/${m[1]}`; return s; }
function mapVehicle(v){ const label=String(v.category||"").trim(); const title=String(v.title||"").trim(); const shortName=title.includes(" - ") ? title.split(" - ").slice(1).join(" - ") : (title || label || "Όχημα"); return { id:v._id, name:shortName, title:title, label, price:Number(v.price)||0, image:toImageUrl(v.image), specs:{ gearbox:v.transmission||"-", fuel:v.fuelType||"-", seats:v.seats||"-", doors:v.doors||"-", bags:v.luggage1||"-", luggage:v.luggage||"-", ac:v.airCondition ? "Ναι" : "Όχι", engineCc:v.engineCc||"-" } }; }
export async function get_vehicles(request){ try{ const category=String(request.query?.category||"all").trim(); let q=wixData.query("VehiclesNew").eq("active", true).ascending("price").limit(1000); if(category && category!=="all" && category!=="default") q=q.eq("category", category); const res=await q.find({ suppressAuth: true }); return respond({success:true, items:(res.items||[]).map(mapVehicle)}); }catch(err){ return respond({success:false,message:err.message||String(err)}, serverError); } }
export async function get_vehicle(request){ try{ const id=String(request.query?.id||"").trim(); if(!id) return respond({success:false,message:"Missing id"}, badRequest); const item=await wixData.get("VehiclesNew", id, { suppressAuth: true }); if(!item || item.active!==true) return respond({success:false,message:"Vehicle not found"}, badRequest); return respond({success:true,item:mapVehicle(item)}); }catch(err){ return respond({success:false,message:err.message||String(err)}, serverError); } }

export async function get_pricing_catalog(request){
  try{
    const catalog = await getPublicPricingCatalog();
    return respond({ success:true, ...catalog });
  }catch(err){
    return respond({ success:false, message: err.message || String(err) }, serverError);
  }
}

function pickLabel(value){ if (!value) return ""; if (typeof value === "object") { return String(value.label || value.title || value.name || value.value || value._id || "").trim(); } return String(value).trim(); }
function asDate(value){ const d = new Date(value); return Number.isNaN(d.getTime()) ? null : d; }
function formatInsuranceLabel(key){ const hit = (INSURANCE_OPTIONS || []).find(item => String(item.key || '').toLowerCase() === String(key || '').toLowerCase()); return hit?.label || String(key || '').toUpperCase() || '—'; }
function deriveSummaryCategory(booking, vehicle){
  const candidates = [vehicle?.label, booking?.categoryId, booking?.category];
  for (const raw of candidates) {
    const s = String(raw || '').trim();
    if (!s) continue;
    if (/^[0-9a-f]{8}-[0-9a-f-]{12,}$/i.test(s)) continue;
    if (s.includes(' - ')) return s.split(' - ')[0].trim();
    const m = s.match(/^([A-Za-z0-9]{1,4})\b/);
    return m ? m[1].trim() : s;
  }
  return '';
}
export async function get_bookingSummary(request){
  try{
    const bookingNumber = String(request.query?.booking || '').trim();
    if(!bookingNumber) return respond({success:false,message:'Missing booking'}, badRequest);

    const res = await wixData.query('BookingsNew').eq('bookingNumber', bookingNumber).limit(1).find({ suppressAuth: true });
    const booking = (res.items || [])[0];
    if(!booking) return respond({success:false,message:'Booking not found'}, badRequest);

    let vehicle = null;
    try {
      if (booking.vehicleId) vehicle = await wixData.get('VehiclesNew', String(booking.vehicleId), { suppressAuth: true });
    } catch (e) {}
    const mappedVehicle = vehicle ? mapVehicle(vehicle) : null;
    const billableDays = Number(booking.billableDays || 0) || (() => {
      const a = asDate(booking.pickupDateTime); const b = asDate(booking.dropoffDateTime);
      if (!a || !b || b <= a) return 1;
      return Math.max(1, Math.ceil((b - a) / 86400000));
    })();
    const snapshot = booking.pricingSnapshot && typeof booking.pricingSnapshot === 'object' ? booking.pricingSnapshot : null;
    const breakdown = snapshot?.breakdown || {};
    const baseCost = Number(breakdown.rental ?? booking.baseCost ?? ((Number(booking.basePricePerDay || 0)) * billableDays) ?? 0);
    const insuranceCost = Number(breakdown.insurance ?? booking.insuranceCost ?? ((Number(booking.insuranceExtraPerDay || 0)) * billableDays) ?? 0);
    const extrasCost = Number(breakdown.options ?? booking.extrasTotal ?? 0);
    const ageFee = Number(breakdown.ageFee ?? booking.ageFee ?? 0);
    const nightFee = Number(breakdown.nightFee ?? booking.nightFee ?? 0);
    const transport = Number(breakdown.transport ?? 0);
    const damages = Number(breakdown.damages ?? 0);
    const surcharges = Number(breakdown.surcharges ?? 0);
    const discount = Number(breakdown.discount ?? 0);
    const recomputedTotal = Number((baseCost + insuranceCost + extrasCost + ageFee + nightFee + transport + damages + surcharges - discount).toFixed(2));
    const storedTotal = Number(snapshot?.breakdown?.gross ?? booking.totalPrice ?? 0);
    const total = recomputedTotal > 0 ? recomputedTotal : storedTotal;

    return respond({ success:true, item:{
      bookingNumber,
      pickup: booking.pickupDateTime || null,
      dropoff: booking.dropoffDateTime || null,
      pickupLocation: pickLabel(booking.pickuppoint),
      dropoffLocation: pickLabel(booking.dropoffpoint),
      vehicleName: mappedVehicle?.name || String(booking.category || 'Κατηγορία οχήματος').trim() || 'Κατηγορία οχήματος',
      vehicleLabel: deriveSummaryCategory(booking, mappedVehicle),
      vehicleImage: mappedVehicle?.image || '',
      insurance: formatInsuranceLabel(booking.selectedPackage || ''),
      extras: String(booking.extras || '').trim() || 'Χωρίς extras',
      baseCost,
      insuranceCost,
      extrasCost,
      locationFee: Number(booking.locationFee ?? transport ?? 0),
      pickupLocationFee: Number(booking.pickupLocationFee ?? 0),
      dropoffLocationFee: Number(booking.dropoffLocationFee ?? 0),
      ageFee,
      nightFee,
      transport,
      damages,
      surcharges,
      discount,
      total,
      days: billableDays,
      pricingSnapshot: snapshot
    }});
  }catch(err){
    return respond({success:false,message:err.message||String(err)}, serverError);
  }
}

function toImageArray(value){
  if (!value) return [];
  if (Array.isArray(value)) return value.flatMap(toImageArray).filter(Boolean);
  if (typeof value === "object") {
    if (value.src || value.url) return [toImageUrl(value.src || value.url)].filter(Boolean);
    return Object.values(value).flatMap(toImageArray).filter(Boolean);
  }
  const url = toImageUrl(value);
  return url ? [url] : [];
}
function normalizeModelKey(value){
  return String(value || "").toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/[^a-z0-9]+/g, "");
}
function modelCategoryFallback(model){
  const key = normalizeModelKey(model);
  const map = {
    hyundaii10:"A", i10:"A", fiatpanda:"A", panda:"A", seatmii:"A", mii:"A",
    skodacitigo:"A", citigo:"A", volkswagenup:"A", vwup:"A", up:"A",
    seatibiza:"B", ibiza:"B", renaultclio:"B", clio:"B", opelcorsa:"B", corsa:"B",
    mercedescla:"LX", cla:"LX", cla200:"LX", mercedescla200:"LX"
  };
  return map[key] || "";
}
function deriveCategoryCode(raw){
  const tryValue = (val) => {
    if (!val) return "";
    if (typeof val === "object") {
      const candidates = [val.category, val.Category, val.code, val.Code, val.title, val.Title, val.name, val.Name, val.label, val.Label];
      for (const c of candidates) {
        const out = tryValue(c);
        if (out) return out;
      }
      return "";
    }
    const s = String(val).trim();
    if (!s) return "";
    if (/^[A-Z]{1,3}$/.test(s)) return s;
    const m = s.match(/^([A-Z]{1,3})\b/);
    if (m) return m[1];
    return "";
  };
  return tryValue(raw);
}
export async function get_fleet_models(request){
  try{
    const vehicleId = String(request.query?.vehicleId || "").trim();
    const requestedCategory = String(request.query?.category || "").trim().toUpperCase();

    let vehicleCategory = "";
    if (vehicleId) {
      try {
        const vehicle = await wixData.get("VehiclesNew", vehicleId, { suppressAuth: true });
        vehicleCategory = String(vehicle?.category || vehicle?.Category || "").trim().toUpperCase();
      } catch (err) {}
    }
    const targetCategory = requestedCategory || vehicleCategory;

    let query = wixData.query("FleetNew").limit(1000);
    try { query = query.include("Category"); } catch (err) {}
    const res = await query.find({ suppressAuth: true });
    const rawItems = res.items || [];

    const grouped = new Map();
    for (const item of rawItems) {
      const active = item?.Active ?? item?.active ?? true;
      if (active === false) continue;

      const model = String(item?.Model || item?.model || item?.Title || item?.title || "").trim();
      if (!model) continue;

      const inferredCategory =
        deriveCategoryCode(item?.Category) ||
        deriveCategoryCode(item?.category) ||
        deriveCategoryCode(item?.categoryCode) ||
        modelCategoryFallback(model);

      if (targetCategory && inferredCategory && inferredCategory !== targetCategory) continue;

      const photos = [
        ...toImageArray(item?.photos),
        ...toImageArray(item?.Photos),
        ...toImageArray(item?.gallery),
        ...toImageArray(item?.Gallery),
        ...toImageArray(item?.images),
        ...toImageArray(item?.Images),
        ...toImageArray(item?.album),
        ...toImageArray(item?.Album),
        ...toImageArray(item?.image),
        ...toImageArray(item?.Image),
        ...toImageArray(item?.photo),
        ...toImageArray(item?.Photo),
      ].filter(Boolean);

      const key = normalizeModelKey(model);
      if (!grouped.has(key)) {
        grouped.set(key, {
          model,
          note: "",
          photos: Array.from(new Set(photos)).slice(0, 3),
          category: inferredCategory || targetCategory || ""
        });
      } else {
        const current = grouped.get(key);
        current.photos = Array.from(new Set([...(current.photos || []), ...photos])).slice(0, 3);
        if (!current.category && inferredCategory) current.category = inferredCategory;
      }
    }

    let items = Array.from(grouped.values()).sort((a,b) => a.model.localeCompare(b.model, "el"));
    if (targetCategory) {
      items = items.filter(item => !item.category || item.category === targetCategory);
    }

    return respond({ success:true, category: targetCategory || "", items });
  }catch(err){
    return respond({ success:false, message: err.message || String(err) }, serverError);
  }
}

export async function post_createBooking(request){ try{ if(!isAllowedMutationOrigin(request)) return respondRestricted(request, {success:false,message:"Origin not allowed"}, badRequest); const payload=await request.body.json(); const result=await createBooking(payload||{}); if(!result?.success) return respondRestricted(request, {success:false,message:result?.message||"Booking failed"}, badRequest); return respondRestricted(request, {success:true, bookingNumber:result.bookingNumber, id:result._id}); }catch(err){ return respondRestricted(request, {success:false,message:err.message||String(err)}, serverError); } }


function htmlResponse(body, fn = ok){ return fn({ headers: {"Content-Type":"text/html; charset=utf-8","Cache-Control":"no-store","Access-Control-Allow-Origin":"*"}, body }); }
function escapeHtml(value){ return String(value ?? '').replace(/[&<>"']/g, (ch) => ({ '&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&#39;' }[ch])); }
function nl2br(value){ return escapeHtml(value).replace(/\n{2,}/g, '</p><p>').replace(/\n/g, '<br>'); }
function richTextBlocks(value, emptyMessage = 'Δεν έχει οριστεί ακόμη περιεχόμενο.') {
  const source = String(value || '').trim();
  if (!source) return `<p>${escapeHtml(emptyMessage)}</p>`;
  return source
    .split(/\n\s*\n/)
    .map((block) => String(block || '').trim())
    .filter(Boolean)
    .map((block) => {
      const lines = block.split(/\n/).map((line) => String(line || '').trim()).filter(Boolean);
      const isList = lines.length > 1 && lines.every((line) => /^[-•]/.test(line));
      if (isList) return `<ul>${lines.map((line) => `<li>${escapeHtml(String(line).replace(/^[-•]\s*/, ''))}</li>`).join('')}</ul>`;
      return `<p>${escapeHtml(block).replace(/\n/g, '<br>')}</p>`;
    })
    .join('');
}
function money(value, currency='EUR'){ const amount = Number(value || 0); const formatted = amount.toLocaleString('el-GR', { minimumFractionDigits: 2, maximumFractionDigits: 2 }); return currency === 'EUR' ? `${formatted}€` : `${formatted} ${currency}`; }
function brandName(settings = {}){ return String(settings?.companyName || 'DIAMOND Rent A Car').trim() || 'DIAMOND Rent A Car'; }
function brandCity(settings = {}){ return String(settings?.companyCity || 'Thessaloniki').trim() || 'Thessaloniki'; }
function brandPhone(settings = {}){ return String(settings?.companyPhone || '+30 2310 000 000').trim() || '+30 2310 000 000'; }
function brandEmail(settings = {}){ return String(settings?.companyEmail || 'info@diamondrentacar.gr').trim() || 'info@diamondrentacar.gr'; }
function brandAddress(settings = {}){ return String(settings?.companyAddress || 'Θεσσαλονίκη, Ελλάδα').trim() || 'Θεσσαλονίκη, Ελλάδα'; }
