export async function get_insurance_terms(request){
  try {
    const catalog = await getPublicPricingCatalog();
    const settings = catalog?.businessSettings || {};
    const plans = Array.isArray(catalog?.insurancePlans) ? catalog.insurancePlans : [];
    const bodyHtml = `
      <p>${nl2br(settings?.insuranceTermsBody || settings?.insuranceTermsIntro || '')}</p>
      <div class="plans">${plans.map((plan) => `<div class="plan"><strong>${escapeHtml(plan.label || plan.key || 'Κάλυψη')}</strong><small>${escapeHtml(plan.description || '')}</small><div class="plan-price">${money(plan.pricePerDay || 0, settings?.currency || 'EUR')} / ημέρα</div></div>`).join('')}</div>`;
    return htmlResponse(bookingUiShell({
      title: `${brandName(settings)} | ${settings?.insuranceTermsTitle || 'Όροι και λεπτομέρειες ασφαλειών'}`,
      kicker: 'Insurance terms',
      heading: settings?.insuranceTermsTitle || 'Όροι και λεπτομέρειες ασφαλειών',
      intro: settings?.insuranceTermsIntro || 'Όσα χρειάζεται να γνωρίζει ο πελάτης πριν επιλέξει κάλυψη.',
      bodyHtml,
      settings,
      actions: [{ href: '/options', label: 'Επιστροφή στα extras', variant: 'btn-light' }, { href: '/booking', label: 'Συνέχεια στην κράτηση', variant: 'btn-primary' }]
    }));
  } catch (err) {
    return htmlResponse(bookingUiShell({ title: 'Insurance terms', kicker: 'Insurance terms', heading: 'Όροι και λεπτομέρειες ασφαλειών', intro: 'Δεν ήταν δυνατή η φόρτωση της σελίδας.', bodyHtml: `<p>${escapeHtml(err?.message || 'Σφάλμα φόρτωσης')}</p>`, settings: {}, actions: [{ href: '/', label: 'Αρχική', variant: 'btn-light' }] }), serverError);
  }
}

export async function get_insurance_details(request){
  try {
    const catalog = await getPublicPricingCatalog();
    const settings = catalog?.businessSettings || {};
    const plans = Array.isArray(catalog?.insurancePlans) ? catalog.insurancePlans : [];
    const bodyHtml = `
      <p>${nl2br(settings?.insuranceDetailsBody || settings?.insuranceDetailsIntro || '')}</p>
      <div class="plans">${plans.map((plan) => `<div class="plan"><strong>${escapeHtml(plan.label || plan.key || 'Κάλυψη')}</strong><small>${escapeHtml(plan.description || '')}</small><div class="plan-price">${money(plan.pricePerDay || 0, settings?.currency || 'EUR')} / ημέρα</div></div>`).join('')}</div>`;
    return htmlResponse(bookingUiShell({
      title: `${brandName(settings)} | ${settings?.insuranceDetailsTitle || 'Λεπτομέρειες ασφαλιστικών επιλογών'}`,
      kicker: 'Insurance details',
      heading: settings?.insuranceDetailsTitle || 'Λεπτομέρειες ασφαλιστικών επιλογών',
      intro: settings?.insuranceDetailsIntro || 'Συνοπτική παρουσίαση των διαθέσιμων καλύψεων και των ημερήσιων χρεώσεων.',
      bodyHtml,
      settings,
      actions: [{ href: '/options', label: 'Επιστροφή στις καλύψεις', variant: 'btn-light' }, { href: '/booking', label: 'Ολοκλήρωση κράτησης', variant: 'btn-primary' }]
    }));
  } catch (err) {
    return htmlResponse(bookingUiShell({ title: 'Insurance details', kicker: 'Insurance details', heading: 'Λεπτομέρειες ασφαλιστικών επιλογών', intro: 'Δεν ήταν δυνατή η φόρτωση της σελίδας.', bodyHtml: `<p>${escapeHtml(err?.message || 'Σφάλμα φόρτωσης')}</p>`, settings: {}, actions: [{ href: '/', label: 'Αρχική', variant: 'btn-light' }] }), serverError);
  }
}

export async function get_rental_terms(request){
  try {
    const catalog = await getPublicPricingCatalog();
    const settings = catalog?.businessSettings || {};
    const plans = Array.isArray(catalog?.insurancePlans) ? catalog.insurancePlans : [];
    const sections = [
      { title: 'Γενικοί όροι', body: settings?.rentalTermsBody || '' },
      { title: 'Προϋποθέσεις οδηγού & εγγύηση', body: settings?.rentalRequirementsBody || '' },
      { title: 'Πολιτικές χρήσης, ακυρώσεων & παραδόσεων', body: settings?.rentalPoliciesBody || '' },
      { title: 'Προσωπικά δεδομένα & λοιπές πληροφορίες', body: settings?.rentalPrivacyBody || '' }
    ];
    const bodyHtml = `
      ${sections.map((section) => `<section class="mini"><h3 style="margin:0 0 10px">${escapeHtml(section.title)}</h3>${richTextBlocks(section.body)}</section>`).join('')}
      <section class="mini"><h3 style="margin:0 0 10px">Ασφαλιστικές επιλογές</h3><div class="plans">${plans.map((plan) => `<div class="plan"><strong>${escapeHtml(plan.label || plan.key || 'Κάλυψη')}</strong><small>${escapeHtml(plan.description || '')}</small><div class="plan-price">${money(plan.pricePerDay || 0, settings?.currency || 'EUR')} / ημέρα</div></div>`).join('')}</div></section>`;
    return htmlResponse(bookingUiShell({
      title: `${brandName(settings)} | ${settings?.rentalTermsTitle || 'Όροι ενοικίασης και πολιτικές'}`,
      kicker: 'Rental terms',
      heading: settings?.rentalTermsTitle || 'Όροι ενοικίασης και πολιτικές',
      intro: settings?.rentalTermsIntro || 'Σημαντικές πληροφορίες για τη μίσθωση, τις προϋποθέσεις και τις πολιτικές της εταιρίας.',
      bodyHtml,
      settings,
      actions: [{ href: '/options', label: 'Επιστροφή στα extras', variant: 'btn-light' }, { href: '/booking', label: 'Συνέχεια στην κράτηση', variant: 'btn-primary' }]
    }));
  } catch (err) {
    return htmlResponse(bookingUiShell({ title: 'Rental terms', kicker: 'Rental terms', heading: 'Όροι ενοικίασης και πολιτικές', intro: 'Δεν ήταν δυνατή η φόρτωση της σελίδας.', bodyHtml: `<p>${escapeHtml(err?.message || 'Σφάλμα φόρτωσης')}</p>`, settings: {}, actions: [{ href: '/', label: 'Αρχική', variant: 'btn-light' }] }), serverError);
  }
}
